/* From Uiverse.io by aryamitra06 - Tags: loader */
.__UIV_SCOPE__ .loader {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .bar {
  display: inline-block;
  width: 3px;
  height: 20px;
  background-color: rgba(255, 255, 255, .5);
  border-radius: 10px;
  animation: scale-up4 1s linear infinite;
}

.__UIV_SCOPE__ .bar:nth-child(2) {
  height: 35px;
  margin: 0 5px;
  animation-delay: .25s;
}

.__UIV_SCOPE__ .bar:nth-child(3) {
  animation-delay: .5s;
}

@keyframes scale-up4 {
  20% {
    background-color: #ffff;
    transform: scaleY(1.5);
  }

  40% {
    transform: scaleY(1);
  }
}
